style.css:
@-moz-document domain("batcave.biz") {
/* ==========================================================
     1. ACTIVE CONFIGURATION PALETTE
     ========================================================== 
     To switch themes manually within this extension, simply swap the 
     uncommented block below to match your chosen aesthetic.
  */

  /* [CHOICE 1: BAT-CAVE DARK - Default] */
  :root {
    --bg-main: #0b0f19 !important;
    --bg-panel: #131a2c !important;
    --bg-card: #1c263f !important;
    --border: #2e3d5e !important;
    --text-primary: #f1f5f9 !important;
    --text-secondary: #94a3b8 !important;
    --accent: #facc15 !important;
  }

  /* [CHOICE 2: METROPOLIS BLUE/RED - To use, uncomment below and comment above]
  :root {
    --bg-main: #0c1424 !important;
    --bg-panel: #152238 !important;
    --bg-card: #1d3152 !important;
    --border: #2b4775 !important;
    --text-primary: #ffffff !important;
    --text-secondary: #93c5fd !important;
    --accent: #ef4444 !important;
  }
  */

  /* ==========================================================
     2. GLOBAL OVERRIDES (Targeting Batcave elements)
     ========================================================== */
  
  /* Background Canvas */
  body, html, #page-wrapper, .main-content {
    background-color: var(--bg-main) !important;
    color: var(--text-primary) !important;
    transition: background-color 0.3s ease !important;
  }

  /* Top Navigation Bars / Sidebars */
  header, nav, .navbar, .sidebar, .top-bar {
    background-color: var(--bg-panel) !important;
    border-color: var(--border) !important;
  }

  /* Content Containers and Comic Grid Cards */
  .comic-card, .manga-box, .card, .panel, .list-group-item {
    background-color: var(--bg-card) !important;
    border: 1px solid var(--border) !important;
    border-radius: 8px !important;
    transition: all 0.2s ease-in-out !important;
  }

  /* Hover States for Interactive Elements */
  .comic-card:hover, .manga-box:hover {
    border-color: var(--accent) !important;
    box-shadow: 0 4px 15px rgba(250, 204, 21, 0.15) !important;
    transform: translateY(-2px) !important;
  }

  /* Headings & Accent Text */
  h1, h2, h3, .title, .logo-text, strong {
    color: var(--text-primary) !important;
  }

  a, .accent-text, span.highlight {
    color: var(--accent) !important;
  }

  a:hover {
    color: var(--text-primary) !important;
    text-decoration: none !important;
  }

  /* Buttons & Layout Controls */
  .btn-primary, button, input[type="submit"] {
    background-color: var(--border) !important;
    color: var(--text-primary) !important;
    border: none !important;
    font-weight: bold !important;
    transition: background-color 0.2s !important;
  }

  /* Make buttons stand out when interacting with custom components */
  .comic-card:hover button, .btn-primary:hover {
    background-color: var(--accent) !important;
    color: var(--bg-main) !important;
  }

  /* Muted Text Descriptions */
  p, .text-muted, .meta-data, .timestamp {
    color: var(--text-secondary) !important;
  }
}
